import React, { useState, useEffect } from 'react';
import {
  TextField,
  IconButton,
  List,
  ListItem,
  ListItemText,
  ListItemAvatar,
  Avatar,
  Typography,
} from '@material-ui/core';
import Stomp from 'stompjs';
import SockJS from 'sockjs-client';
import styles from'./App.module.css';

const App = () => {
  const [messages, setMessages] = useState([]);
  const [message, setMessage] = useState('');
  const [nickname, setNickname] = useState('');
  const [stompClient, setStompClient] = useState(null);

  useEffect(() => {
    const socket = new SockJS('http://localhost:8080/ws');
    const client = Stomp.over(socket);

    client.connect({}, () => {
      client.subscribe('/topic/messages', (message) => {
        const receivedMessage = JSON.parse(message.body);
        setMessages((prevMessages) => [...prevMessages, receivedMessage]);
      });
    });

    setStompClient(client);

    return () => {
      client.disconnect();
    };
  }, []);

  const handleNicknameChange = (event) => {
    setNickname(event.target.value);
  };

  const handleMessageChange = (event) => {
    setMessage(event.target.value);
  };

  const sendMessage = () => {
    if (message.trim()) {
      const chatMessage = {
        nickname,
        content: message,
      };

      stompClient.send('/app/chat', {}, JSON.stringify(chatMessage));
      setMessage('');
    }
  };
  return (
    <div className="h-screen bg-gray-100 flex">
      {/* Sidebar */}
      <div className="w-80 bg-white border-r border-gray-200 flex flex-col">
        <div className="p-4 border-b border-gray-200">
          <div className="flex items-center justify-between mb-4">
            <h1 className="text-xl font-semibold text-gray-800">Сообщения</h1>
            <button className="text-gray-600 hover:text-gray-800">
              <Menu size={20} />
            </button>
          </div>
          <div className="relative">
            <input
              type="text"
              placeholder="Поиск чатов"
              className="w-full pl-10 pr-4 py-2 bg-gray-50 border border-gray-200 rounded-lg focus:outline-none focus:border-blue-500"
            />
            <Search className="absolute left-3 top-2.5 text-gray-400" size={18} />
          </div>
        </div>

        {/* Chat list */}
        <div className="flex-1 overflow-y-auto">
          {[1, 2, 3].map((chat) => (
            <div key={chat} className="flex items-center p-4 hover:bg-gray-50 cursor-pointer border-b border-gray-100">
              <img
                src={`https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=80&h=80&fit=crop`}
                alt="User avatar"
                className="w-12 h-12 rounded-full object-cover"
              />
              <div className="ml-4 flex-1">
                <div className="flex items-center justify-between">
                  <h3 className="font-medium text-gray-900">Пользователь {chat}</h3>
                  <span className="text-sm text-gray-500">14:30</span>
                </div>
                <p className="text-sm text-gray-500 truncate">Последнее сообщение в чате...</p>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Main chat area */}
      <div className="flex-1 flex flex-col">
        {/* Chat header */}
        <div className="h-16 border-b border-gray-200 flex items-center px-6 bg-white">
          <div className="flex items-center">
            <img
              src="https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=80&h=80&fit=crop"
              alt="Current chat"
              className="w-10 h-10 rounded-full object-cover"
            />
            <div className="ml-4">
              <h2 className="font-medium text-gray-900">Иван Петров</h2>
              <p className="text-sm text-gray-500">Онлайн</p>
            </div>
          </div>
        </div>

        {/* Messages */}
        <div className="flex-1 overflow-y-auto bg-gray-50 p-6">
          {/* Received message */}
          <div className="flex mb-4">
            <img
              src="https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=80&h=80&fit=crop"
              alt="User"
              className="w-8 h-8 rounded-full object-cover"
            />
            <div className="ml-3 max-w-md">
              <div className="bg-white rounded-lg p-3 shadow-sm">
                <p className="text-gray-800">Привет! Как дела?</p>
              </div>
              <span className="text-xs text-gray-500 mt-1">14:30</span>
            </div>
          </div>

          {/* Sent message */}
          <div className="flex flex-row-reverse mb-4">
            <div className="max-w-md">
              <div className="bg-blue-500 text-white rounded-lg p-3 shadow-sm">
                <p>Привет! Все хорошо, спасибо!</p>
              </div>
              <span className="text-xs text-gray-500 mt-1 float-right">14:31</span>
            </div>
          </div>
        </div>

        {/* Message input */}
        <div className="h-24 border-t border-gray-200 p-4 bg-white">
          <div className="flex items-center">
            <button className="p-2 text-gray-500 hover:text-gray-700 rounded-lg hover:bg-gray-100">
              <Paperclip size={20} />
            </button>
            <button className="p-2 text-gray-500 hover:text-gray-700 rounded-lg hover:bg-gray-100">
              <Image size={20} />
            </button>
            <div className="flex-1 mx-4">
              <input
                type="text"
                placeholder="Написать сообщение..."
                className="w-full px-4 py-2 border border-gray-200 rounded-lg focus:outline-none focus:border-blue-500"
              />
            </div>
            <button className="p-2 text-gray-500 hover:text-gray-700 rounded-lg hover:bg-gray-100">
              <Smile size={20} />
            </button>
            <button className="ml-2 px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 flex items-center">
              <Send size={18} />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
  /* return (
    <div className={styles.container}>
      <List className={styles.chatBox}>
        {messages.map((msg, index) => (
          <ListItem key={index}>
            <ListItemAvatar>
              <Avatar>{msg.nickname.charAt(0)}</Avatar>
            </ListItemAvatar>
            <ListItemText
              primary={
                <Typography variant="subtitle1">{msg.nickname}</Typography>
              }
              secondary={msg.content}
            />
          </ListItem>
        ))}
      </List>

      <div className={styles.sendMessage}>
        <TextField
          placeholder="Enter your nickname"
          value={nickname}
          onChange={handleNicknameChange}
          autoFocus
        />
        <TextField
          placeholder="Type a message"
          value={message}
          onChange={handleMessageChange}
          fullWidth
        />
        <IconButton onClick={sendMessage} disabled={!message.trim()}>
          send
        </IconButton>
        <div className={styles.chatButtons}>
          <button id="btn-attach">Прикрепить файл</button>
          <button id="btn-emoji">Эмодзи</button>
          <button id="btn-clear">Очистить чат</button>
        </div>
      </div>
    </div>
  ); */
};

export default App;
